    def readints():
        return map(int, sys.stdin.readline().split())

    def solve(n, S, edges):
        graph = defaultdict(list)
        for v, u, w, c in edges:
            graph[v].append((u, w, c))
            graph[u].append((v, w, c))

        leaves = []
        q = [(0, 1, 0)]
        visited = set()
        while q:
            dist, node, parent = heapq.heappop(q)
            if node in visited:
                continue
            visited.add(node)
            is_leaf = True
            for neighbor, weight, cost in graph[node]:
                if neighbor != parent:
                    is_leaf = False
                    heapq.heappush(q, (dist + weight, neighbor, node))
            if is_leaf:
                leaves.append((node, dist))

        moves = []
        for leaf, dist in leaves:
            current_weight = dist
            level = 0
            while current_weight > 0:
                heapq.heappush(moves, (-level, current_weight, leaf))
                current_weight //= 2
                level += 1

        total_cost = 0
        while S < sum(-move[1] for move in moves):
            _, weight, leaf = heapq.heappop(moves)
            if weight % 2 == 0:
                cost = 1
            else:
                cost = 2
            for v, u, c in edges:
                if (v, u) == (leaf, parent[leaf]) or (u, v) == (leaf, parent[leaf]):
                    cost = c
                    break
            total_cost += cost
            new_weight = weight // 2
            if new_weight > 0:
                heapq.heappush(moves, (-level - 1, new_weight, leaf))

        return total_cost

